$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "====================================================" -ForegroundColor Cyan
Write-Host " MemeScope FULL SOURCE RECOVERY" -ForegroundColor Cyan
Write-Host "====================================================" -ForegroundColor Cyan
Write-Host ""

$root = (Get-Location).Path
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

if (!(Test-Path -LiteralPath (Join-Path $root "package.json"))) {
    throw "package.json tidak ditemukan. Jalankan dari root folder memecoin-analyst."
}

if (!(Test-Path -LiteralPath (Join-Path $root "src"))) {
    throw "Folder src tidak ditemukan."
}

# Full backup before touching anything.
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $root ".backup-full-recovery-$stamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

Copy-Item -LiteralPath (Join-Path $root "src") `
    -Destination (Join-Path $backupRoot "src") `
    -Recurse -Force

foreach ($file in @(
    "package.json",
    "next.config.ts",
    "eslint.config.mjs",
    ".env.example"
)) {
    $source = Join-Path $root $file
    if (Test-Path -LiteralPath $source) {
        Copy-Item -LiteralPath $source `
            -Destination (Join-Path $backupRoot $file) `
            -Force
    }
}

Write-Host "Backup penuh dibuat:" -ForegroundColor Green
Write-Host "  $backupRoot" -ForegroundColor DarkGray
Write-Host ""

function Write-Base64Utf8File {
    param(
        [Parameter(Mandatory=$true)][string]$RelativePath,
        [Parameter(Mandatory=$true)][string]$Base64
    )

    $full = Join-Path $root $RelativePath
    $dir = Split-Path -Parent $full

    if ($dir -and !(Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
    }

    $bytes = [Convert]::FromBase64String($Base64)
    $text = [System.Text.Encoding]::UTF8.GetString($bytes)

    [System.IO.File]::WriteAllText(
        $full,
        $text,
        $utf8NoBom
    )
}

function Run-EmbeddedStage {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][string]$Base64
    )

    $tempDir = Join-Path $root ".recovery-stage-scripts"
    New-Item -ItemType Directory -Force -Path $tempDir | Out-Null

    $tempPath = Join-Path $tempDir $Name
    $bytes = [Convert]::FromBase64String($Base64)
    $text = [System.Text.Encoding]::UTF8.GetString($bytes)

    [System.IO.File]::WriteAllText(
        $tempPath,
        $text,
        $utf8NoBom
    )

    Write-Host ""
    Write-Host "==> Restoring $Name" -ForegroundColor Cyan

    & powershell.exe `
        -NoProfile `
        -ExecutionPolicy Bypass `
        -File $tempPath

    if ($LASTEXITCODE -ne 0) {
        throw "$Name gagal dengan exit code $LASTEXITCODE"
    }
}

