# ---------------------------------------------------------
# Discover: unique React social keys
# ---------------------------------------------------------
$discoverPath = Join-Path $root "src/app/discover/page.tsx"

if (Test-Path -LiteralPath $discoverPath) {
    $discover = [System.IO.File]::ReadAllText($discoverPath)

    $discover = $discover.Replace(
        ".map((social) => (",
        ".map((social, index) => ("
    )

    $discover = $discover.Replace(
        'key={`${social.platform}-${social.handle}`}',
        'key={`${token.address}-${social.platform}-${social.handle || index}`}'
    )

    [System.IO.File]::WriteAllText(
        $discoverPath,
        $discover,
        $utf8NoBom
    )

    Write-Host "Discover duplicate-key fix applied." -ForegroundColor Green
}

# ---------------------------------------------------------
# Risk analyzer: retry 429 automatically
# ---------------------------------------------------------
$riskPath = Join-Path $root "src/app/api/risk/solana/[address]/route.ts"

if (Test-Path -LiteralPath $riskPath) {
    $risk = [System.IO.File]::ReadAllText($riskPath)

    $rpcPattern = 'async function rpc\([\s\S]*?return data\.result;\r?\n\}'

    $rpcReplacement = @'
async function rpc(
  rpcUrl: string,
  method: string,
  params: unknown[],
  id: number,
) {
  const maxAttempts = 4;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const response = await fetch(rpcUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id,
        method,
        params,
      }),
      cache: "no-store",
    });

    if (response.status === 429) {
      const retryAfterHeader =
        response.headers.get("retry-after");

      const waitMs =
        retryAfterHeader &&
        Number.isFinite(Number(retryAfterHeader))
          ? Number(retryAfterHeader) * 1000
          : Math.min(8000, 750 * 2 ** (attempt - 1));

      if (attempt === maxAttempts) {
        throw new Error(
          "Solana RPC rate limit reached. Configure SOLANA_RPC_URL for stable real-time data.",
        );
      }

      await new Promise((resolve) =>
        setTimeout(resolve, waitMs),
      );

      continue;
    }

    if (!response.ok) {
      throw new Error(`Solana RPC ${response.status}`);
    }

    const data = (await response.json()) as Json;

    if (data.error) {
      throw new Error(
        data.error.message || `RPC ${method} returned an error`,
      );
    }

    return data.result;
  }

  throw new Error("Solana RPC request failed.");
}
'@

    $risk = [regex]::Replace(
        $risk,
        $rpcPattern,
        $rpcReplacement,
        1
    )

    # Gracefully skip holder concentration when provider rejects large-account queries.
    $promisePattern = '(?s)const \[mintAccount,\s*supplyResult,\s*largestResult,\s*dexPairs\]\s*=\s*await Promise\.all\(\[\s*rpc\(\s*rpcUrl,\s*"getAccountInfo",.*?fetchDexPairs\(address\),\s*\]\);'

    $promiseReplacement = @'
const [mintAccount, supplyResult, dexPairs] =
      await Promise.all([
        rpc(
          rpcUrl,
          "getAccountInfo",
          [
            address,
            {
              encoding: "jsonParsed",
              commitment: "confirmed",
            },
          ],
          1,
        ),
        rpc(
          rpcUrl,
          "getTokenSupply",
          [address, { commitment: "confirmed" }],
          2,
        ),
        fetchDexPairs(address),
      ]);

    let largestResult: Json = { value: [] };
    let concentrationAvailable = true;

    try {
      largestResult = await rpc(
        rpcUrl,
        "getTokenLargestAccounts",
        [address, { commitment: "confirmed" }],
        3,
      );
    } catch (error) {
      concentrationAvailable = false;

      console.warn(
        "[Risk Analyzer] Holder concentration unavailable:",
        error instanceof Error ? error.message : error,
      );
    }
'@

    $risk = [regex]::Replace(
        $risk,
        $promisePattern,
        $promiseReplacement,
        1
    )

    $riskBuildPattern = '(?s)(const risk = buildRisk\(\{\s*mintAuthorityDisabled,\s*freezeAuthorityDisabled,\s*top1,\s*top10,\s*market,\s*\}\);)'

    $riskBuildReplacement = @'
$1

    if (!concentrationAvailable) {
      risk.flags = risk.flags.filter(
        (flag) =>
          flag.id !== "top1-ok" &&
          flag.id !== "top10-ok",
      );

      risk.flags.push({
        id: "holder-data-unavailable",
        title: "Holder concentration unavailable",
        description:
          "The RPC provider could not safely query holder concentration for this mint. Holder concentration is excluded from this analysis.",
        severity: "warning",
        points: 0,
      });
    }
'@

    $risk = [regex]::Replace(
        $risk,
        $riskBuildPattern,
        $riskBuildReplacement,
        1
    )

    $oldLimitation = '"Largest-account concentration is derived from the 20 largest SPL token accounts returned by RPC and aggregated by parsed owner.",'

    $newLimitation = @'
concentrationAvailable
          ? "Largest-account concentration is derived from the 20 largest SPL token accounts returned by RPC and aggregated by parsed owner."
          : "Holder concentration could not be retrieved for this mint because the RPC provider rejected the large-account query. Concentration is not treated as safe or unsafe.",
'@

    if ($risk.Contains($oldLimitation)) {
        $risk = $risk.Replace(
            $oldLimitation,
            $newLimitation
        )
    }

    [System.IO.File]::WriteAllText(
        $riskPath,
        $risk,
        $utf8NoBom
    )

    Write-Host "Risk analyzer compatibility fixes applied." -ForegroundColor Green
}

# ---------------------------------------------------------
# AI analyst: don't treat unavailable holders as safe
# ---------------------------------------------------------
$aiPath = Join-Path $root "src/app/api/ai/analyze/route.ts"

if (Test-Path -LiteralPath $aiPath) {
    $ai = [System.IO.File]::ReadAllText($aiPath)

    if (
        $ai.Contains("top10Percentage: number;") -and
        !$ai.Contains("analyzedOwnerCount: number;")
    ) {
        $ai = $ai.Replace(
            "top10Percentage: number;",
            "top10Percentage: number;`r`n  analyzedOwnerCount: number;"
        )
    }

    $oldAi = @'
if (report.top10Percentage <= 25) {
    strengths.push(`Observed top-10 concentration is relatively distributed at ${report.top10Percentage.toFixed(1)}%.`);
  } else if (report.top10Percentage >= 40) {
    risks.push(`Observed top-10 concentration is elevated at ${report.top10Percentage.toFixed(1)}%.`);
  } else {
    watch.push(`Top-10 concentration is ${report.top10Percentage.toFixed(1)}%; inspect owner types before drawing conclusions.`);
  }
'@

    $newAi = @'
if (report.analyzedOwnerCount <= 0) {
    watch.push(
      "Holder concentration data is unavailable for this mint, so no holder-distribution conclusion is made.",
    );
  } else if (report.top10Percentage <= 25) {
    strengths.push(`Observed top-10 concentration is relatively distributed at ${report.top10Percentage.toFixed(1)}%.`);
  } else if (report.top10Percentage >= 40) {
    risks.push(`Observed top-10 concentration is elevated at ${report.top10Percentage.toFixed(1)}%.`);
  } else {
    watch.push(`Top-10 concentration is ${report.top10Percentage.toFixed(1)}%; inspect owner types before drawing conclusions.`);
  }
'@

    if ($ai.Contains($oldAi)) {
        $ai = $ai.Replace($oldAi, $newAi)
    }

    if (
        $ai.Contains("top10Percentage: report.top10Percentage,") -and
        !$ai.Contains("analyzedOwnerCount: report.analyzedOwnerCount,")
    ) {
        $ai = $ai.Replace(
            "top10Percentage: report.top10Percentage,",
            "top10Percentage: report.top10Percentage,`r`n    analyzedOwnerCount: report.analyzedOwnerCount,"
        )
    }

    [System.IO.File]::WriteAllText(
        $aiPath,
        $ai,
        $utf8NoBom
    )

    Write-Host "AI holder-data fallback applied." -ForegroundColor Green
}

