    $oldDisplay = '{(value as number).toFixed(1)}%'
    $newDisplay = @'
{report.analyzedOwnerCount > 0
                          ? `${(value as number).toFixed(1)}%`
                          : "N/A"}
'@

    if ($page.Contains($oldDisplay)) {
        $page = $page.Replace(
            $oldDisplay,
            $newDisplay
        )
    }

    [System.IO.File]::WriteAllText(
        $tokenPath,
        $page,
        $utf8NoBom
    )
}

# ---------------------------------------------------------
# Normalize package.json only (avoid BOM JSON parser issue)
# ---------------------------------------------------------
$packagePath = Join-Path $root "package.json"

if (Test-Path -LiteralPath $packagePath) {
    $packageText = [System.IO.File]::ReadAllText($packagePath)
    $packageText = $packageText.TrimStart([char]0xFEFF)

    [System.IO.File]::WriteAllText(
        $packagePath,
        $packageText,
        $utf8NoBom
    )
}

